import json,sys,re
p=sys.argv[1]
for line in open(p):
    try: d=json.loads(line)
    except: continue
    if d.get('type')!='response_item': continue
    payload=d.get('payload',{})
    if payload.get('role')=='user':
        s=json.dumps(payload)
        if re.search(r'Phase|phase', s) and 'system' not in s[:200]:
