            texts=[]
            for c in payload.get('content',[]):
                if c.get('type') in ('input_text','text'):
                    texts.append(c.get('text',''))
            t='\n'.join(texts)
            if t.strip():
                print(t[:1500])
                print('-----')
EOF
done

