652: function spiritStateFor(
653:   project: WorkshopProject,
654:   section: WorkshopProject["sections"][number] | null,
655: ): SpiritState {
656:   if (project.stage === "ORACLE") {
657:     return project.product.status === "PROPOSED" ? "clarification" : "listening";
658:   }
659:   if (project.stage === "ARCHITECT") {
660:     return section && (section.status === "DRAFT" || section.status === "STALE") ? "drawing" : "approval";
661:   }
662:   if (project.stage === "MAKER") {
663:     const latest = [...project.operations].reverse().find((operation) => operation.kind === "maker");
664:     if (!latest) return "idle";
665:     if (latest.status === "WAITING_PERMISSION") return "permission";
666:     if (latest.status === "ABANDONED" || latest.status === "COMPLETED_UNAPPLIED") return "permission";
667:     if (latest.status === "FAILED" || latest.status === "CANCELLED") return "blocked";
668:     if (latest.status === "SUCCEEDED") return "success";
669:     return "building";
670:   }
671:   if (project.evidence.some((item) => item.result === "FAIL" || item.result === "INCONCLUSIVE")) return "warning";
672:   if (project.witnessDrafts.length > 0) return "evidence";
673:   return "scanning";
674: }

