464:   private diagnosticsFor(discovery: OpenCodeDiscovery, selected: ModelRef | null, accessMode: ModelAccessMode) {
465:     const diagnostics: ConnectionStatus["diagnostics"] = [];
466:     if (discovery.server.warning) {
467:       diagnostics.push({
468:         code: "VERSION_UNTESTED",
469:         severity: "warning",
470:         title: "Untested OpenCode patch version",
471:         message: discovery.server.warning,
472:         repair: `Use OpenCode ${discovery.server.testedVersion} for the tested surface, or verify the new version with the live diagnostic.`,
473:       });
474:     }
475:     if (discovery.models.length === 0) {
476:       diagnostics.push({
477:         code: "NO_MODELS",
478:         severity: "error",
479:         title: "No models reported",
480:         message: "OpenCode returned no selectable models.",
481:         repair: "Connect a provider inside OpenCode (`/connect`), then run `/models` or restart the server. This app never asks for provider API keys.",
482:       });
483:     }
484:     const availableModels = discovery.models.filter((model) => model.availability === "available");
485:     if (discovery.models.length > 0 && availableModels.length === 0) {
486:       diagnostics.push({
487:         code: "NO_AVAILABLE_MODELS",
488:         severity: "error",
489:         title: "No available models",
490:         message: "Every model in the catalog is disabled or tied to a disabled provider.",
491:         repair: "Enable a provider/model inside OpenCode, then retry discovery.",
492:       });
493:     }
494:     for (const provider of discovery.providers.filter((item) => item.ready === "needs_auth")) {
495:       diagnostics.push({
496:         code: "PROVIDER_NOT_CONNECTED",
497:         severity: "warning",
498:         title: `${provider.name} needs authentication`,
499:         message: provider.detail,
500:         repair: `Connect ${provider.name} inside OpenCode with /connect, or choose a model from a provider that is already available.`,
501:       });
502:     }
503:     if (selected) {
504:       const match = discovery.models.find((model) => model.providerID === selected.providerID && model.id === selected.id);
505:       if (!match) {
506:         diagnostics.push({
507:           code: "MODEL_UNAVAILABLE",
508:           severity: "error",
509:           title: "Selected model is unavailable",
510:           message: `${selected.providerID}/${selected.id} is not in the current OpenCode catalog.`,
511:           repair: "Choose another model in the OpenCode panel. The previous selection was not replaced automatically.",
512:         });
513:       } else if (match.availability !== "available") {
514:         diagnostics.push({
515:           code: "MODEL_DISABLED",
516:           severity: "error",
517:           title: "Selected model is disabled",
518:           message: `${match.name} is present but unavailable (${match.status}).`,
519:           repair: "Enable the model or provider inside OpenCode, or choose another model.",
520:         });
521:       } else if (!modelAllowed(match, accessMode)) {
522:         diagnostics.push({
523:           code: "MODEL_ACCESS_POLICY_BLOCKED",
524:           severity: "error",
525:           title: "Selected model is blocked by the access preference",
526:           message: `${match.name} reports paid or unknown remote pricing while this project is set to Free and local only.`,
527:           repair: "Choose a free/local model, or deliberately change Model access to All accessible models. The app will not substitute a model.",
528:         });
529:       } else if (selected.variant && !match.variants.includes(selected.variant)) {
530:         diagnostics.push({
531:           code: "VARIANT_UNAVAILABLE",
532:           severity: "error",
533:           title: "Selected variant is not reported",
534:           message: `Variant "${selected.variant}" is not attached to ${match.key}. Reported variants: ${match.variants.join(", ") || "none"}.`,
535:           repair: "Choose a variant reported for this model, or use the model default.",
536:         });
537:       }
538:       if (match?.local && ((match.limits.context ?? 0) < 8_192 || (match.limits.output ?? 0) < 1_024)) {
539:         diagnostics.push({
540:           code: "LOCAL_MODEL_LIMITS",
541:           severity: "warning",
542:           title: "Local model has small limits",
543:           message: `${match.name} reports a ${match.limits.context ?? "unknown"} token context and ${match.limits.output ?? "unknown"} token output limit.`,
544:           repair: "Lower the planned scope, increase the local model context/output in its runtime, or choose a model with larger limits. OpenCode does not report free RAM or VRAM.",
545:         });
546:       }
547:     }
548:     if (discovery.permissions.length > 0) {
549:       diagnostics.push({
550:         code: "PERMISSION_PENDING",
551:         severity: "warning",
552:         title: "Permission decisions are waiting",
553:         message: `${discovery.permissions.length} OpenCode permission request(s) need a human decision.`,
554:         repair: "Review each request in the OpenCode panel. This application never auto-approves a request.",
555:       });
556:     }
557:     return diagnostics;
558:   }
