260:   async reconcile(actionId: string, expectedRevision: number, operationId: string) {
261:     const payload = { operationId, intent: "reconcile" };
262:     const claimed = await this.claim(actionId, payload, expectedRevision);
263:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
264:     const operation = claimed.project.operations.find((item) => item.id === operationId);
265:     if (!operation?.nativeSessionId) {
266:       throw new ExperienceFailure("This operation has no native session to reconcile.", "NOTHING_TO_RECONCILE", 409, false);
267:     }
268:     if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
269:       throw new ExperienceFailure("A finished operation does not need reconciliation.", "ALREADY_FINISHED", 409, false);
270:     }
271:     const role = operation.kind === "maker" ? "maker" : operation.kind === "witness" ? "witness" : "architect";
272:     const observed = await this.guide.inspect(operation.nativeSessionId, {
273:       conversationId: claimed.project.id,
274:       role,
275:     });
276:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
277:       const next = structuredClone(project);
278:       const current = next.operations.find((item) => item.id === operationId);
279:       if (!current) throw new WorkflowConflict("That operation is not in this project.");
280:       if (observed === "running") {
281:         current.status = "RUNNING";
282:         current.result = "Native session is still running. It was not started again.";
283:       } else if (observed === "succeeded") {
284:         current.status = "SUCCEEDED";
285:         current.finishedAt ??= new Date().toISOString();
286:         current.result = "Reconciled from the native session outcome.";
287:       } else if (observed === "failed") {
288:         current.status = "FAILED";
289:         current.finishedAt ??= new Date().toISOString();
290:         current.result = "Reconciled from a failed or interrupted native session.";
291:       } else {
292:         current.status = "ABANDONED";
293:         current.statusReason = "native-outcome-unconfirmed";
294:         current.lastObservedAt = new Date().toISOString();
295:         current.result = "Native outcome is still unknown. This action was not repeated.";
296:       }
297:       return refreshNextAction(next);
298:     });
299:   }
