692: 
693: function classifyNativeError(error: unknown): {
694:   code: string;
695:   status: number;
696:   retryable: boolean;
697:   unknown: boolean;
698:   message: string;
699: } {
700:   const declared = typeof (error as { code?: unknown })?.code === "string" ? (error as { code: string }).code : null;
701:   if (declared === "ENGINE_AUTH") {
702:     return { code: "ENGINE_AUTH", status: 503, retryable: false, unknown: false, message: "OpenCode rejected the configured credentials." };
703:   }
704:   if (error instanceof ProviderRequestError) {
705:     return {
706:       code: error.details.category,
707:       status: error.details.technical.statusCode && error.details.technical.statusCode >= 400
708:         ? error.details.technical.statusCode
709:         : 502,
710:       retryable: error.details.retryable,
711:       unknown: false,
712:       message: error.details.whatHappened,
713:     };
714:   }
715:   if (declared === "ENGINE_INCOMPATIBLE" || declared === "MODEL_UNAVAILABLE" || declared === "MODEL_CHANGED") {
716:     return { code: declared, status: 503, retryable: false, unknown: false, message: error instanceof Error ? error.message : "OpenCode is not ready for this build." };
717:   }
718:   if (declared === "ENGINE_UNAVAILABLE") {
719:     return { code: "ENGINE_UNAVAILABLE", status: 503, retryable: true, unknown: false, message: "OpenCode is unavailable. No native work was started." };
720:   }
721:   if (error instanceof NativeBudgetError) {
722:     return { code: "BUDGET_EXCEEDED", status: 409, retryable: false, unknown: false, message: error.message };
723:   }
724:   if (error instanceof NativeSessionError) {
725:     return { code: error.code, status: 502, retryable: false, unknown: false, message: error.message };
726:   }
727:   if (error instanceof NativeTimeoutError) {
728:     return { code: "NATIVE_UNKNOWN", status: 503, retryable: false, unknown: true, message: "The native run timed out. Reconcile the native session before any new run." };
729:   }
730:   if (error instanceof NetworkPolicyError) {
731:     return { code: "NATIVE_UNKNOWN", status: 503, retryable: false, unknown: true, message: error.message };
732:   }
733:   const message = error instanceof Error ? error.message : "The native spirit could not be reached.";
734:   if (/\b429\b|rate limit|quota|provider limit|too many requests/i.test(message)) {
735:     return { code: "PROVIDER_LIMITED", status: 429, retryable: true, unknown: false, message: "The provider is limiting requests. No automatic retry was attempted." };
736:   }
737:   if (/\b401\b|\b403\b|unauthori[sz]ed|forbidden|authentication/i.test(message)) {
738:     return { code: "ENGINE_AUTH", status: 503, retryable: false, unknown: false, message: "OpenCode rejected the configured credentials." };
739:   }
740:   if (/\b404\b|version|incompatible/i.test(message)) {
