590:   private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
591:     const loaded = await this.store.load();
592:     const hash = payloadHash(payload);
593:     const existing = loaded.state.actions.find((action) => action.id === actionId);
594:     if (existing) {
595:       if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
596:       return { project: loaded.state, duplicate: true };
597:     }
598:     if (loaded.state.revision !== expectedRevision) {
599:       throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
600:     }
601:     return { project: loaded.state, duplicate: false };
602:   }
