613:     const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
614:       const next = structuredClone(project);
615:       next.operations.push({
616:         id: randomUUID(),
617:         kind: role === "witness" ? "witness" : "guide",
618:         payloadHash: payloadHash(payload),
619:         nativeSessionId: sessionId,
620:         nativeMessageId: null,
621:         status: "FAILED",
622:         result: safeMessage,
623:         model: project.engine.model,
624:         agent: null,
625:         startedAt: new Date().toISOString(),
626:         finishedAt: new Date().toISOString(),
627:         statusReason: "malformed-response",
628:         lastObservedAt: new Date().toISOString(),
629:         appliedAt: null,
630:         providerError: null,
631:       });
632:       rememberTranscript(next, "system", safeMessage);
633:       return refreshNextAction(next);
634:     });
635:     throw new ExperienceFailure(safeMessage, "MALFORMED_RESPONSE", 400, true, saved.project.operations.at(-1)?.id ?? null);
