752: function providerErrorFor(
753:   error: unknown,
754:   provider: string,
755:   sessionReference: string | null,
756:   savedWorkChanged: "no" | "possibly",
757: ): ProviderRequestError | null {
758:   const code = typeof (error as { code?: unknown })?.code === "string" ? (error as { code: string }).code : "";
759:   if ([
760:     "ENGINE_AUTH",
761:     "ENGINE_INCOMPATIBLE",
762:     "ENGINE_UNAVAILABLE",
763:     "MODEL_CHANGED",
764:     "BUDGET_EXCEEDED",
765:     "NATIVE_TIMEOUT",
766:     "EMPTY_RESPONSE",
767:   ].includes(code) || error instanceof NetworkPolicyError) return null;
768:   return classifyProviderError(error, { provider, sessionReference, savedWorkChanged });
769: }
