content.text:
.onboarding-head {
  display: flex;
  gap: var(--space-4);
  justify-content: space-between;
  align-items: start;
}

.onboarding h1 {
  margin-bottom: var(--space-2);
}

.wizard-steps {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.wizard-steps li {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: 999px;
  background: var(--raised);
  color: var(--muted);
}

.wizard-steps li.current {
  color: var(--accent);
  outline: 1px solid var(--accent);
}

.wizard-steps li.done {
  color: var(--success);
}

.wizard-grid {
  display: grid;
  gap: var(--space-4);
}

.wizard-card {
  background: var(--bg);
  border: 1px solid rgb(184 175 202 / 28%);
  border-radius: 14px;
  padding: var(--space-4);
}

.wizard-card h2 {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.wizard-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

input,
select {
  width: 100%;
  box-sizing: border-box;
  min-height: 44px;
  border-radius: 10px;
  border: 1px solid rgb(184 175 202 / 40%);
  background: var(--bg);
  color: var(--text);
  font: inherit;
  padding: var(--space-2) var(--space-3);
}

input[type="radio"] {
  width: auto;
  min-height: 0;
}

input:disabled,
select:disabled {
  opacity: 0.6;
}

code,
.command {
  font-family: ui-monospace, monospace;
  font-size: 0.9em;
}

.command {
  display: block;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  background: var(--raised);
  border-radius: 10px;
  padding: var(--space-3);
}

.wizard-card .note {
  margin-top: var(--space-3);
}

.model-list {
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-3);
  max-height: 45vh;
  overflow: auto;
}

.model-option {
  display: flex;
  gap: var(--space-3);
  align-items: start;
  margin-top: 0;
  padding: var(--space-3);
  border-radius: 12px;
  border: 1px solid rgb(184 175 202 / 24%);
  background: var(--surface);
  cursor: pointer;
}

.model-option.selected {
  border-color: var(--accent);
}

.model-option > span {
  display: grid;
  gap: 2px;
}

.model-facts {
  color: var(--muted);
  font-size: 0.88rem;
}

.model-detail {
  margin-top: var(--space-3);
  padding-top: var(--space-3);
  border-top: 1px solid rgb(184 175 202 / 24%);
}

.discovery-summary {
  display: grid;
  gap: var(--space-1);
  margin-bottom: var(--space-3);
}

.connection-summary {
  display: grid;
  gap: var(--space-2);
  border-radius: 12px;
  padding: var(--space-3);
  background: var(--raised);
}

.connection-summary.good {

.discovery-columns {
  display: grid;
  gap: var(--space-3);
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

a {
  color: var(--accent);
}

@media (min-width: 860px) {
  .wizard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (prefers-contrast: more) {
  .model-option,
  .wizard-card,
  input,
  select,
  .advanced {
    border-width: 2px;
    border-color: var(--text);
  }
}

